use async_trait::async_trait;
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::Mutex;

use super::{PlayerKey, PlayerState, Session, StateStore};

#[derive(Default, Clone)]
pub struct MemoryStateStore {
    inner: Arc<Inner>,
}

#[derive(Default)]
struct Inner {
    sessions: DashMap<String, Session>,
    players: DashMap<PlayerKey, PlayerState>,
    locks: DashMap<PlayerKey, Arc<Mutex<()>>>,
}

impl MemoryStateStore {
    pub fn new() -> Self {
        Self::default()
    }
}

#[async_trait]
impl StateStore for MemoryStateStore {
    async fn save_session(&self, session: Session) {
        self.inner.sessions.insert(session.session_id.clone(), session);
    }

    async fn get_session(&self, session_id: &str) -> Option<Session> {
        self.inner.sessions.get(session_id).map(|s| s.clone())
    }

    async fn delete_session(&self, session_id: &str) {
        self.inner.sessions.remove(session_id);
    }

    async fn list_sessions(&self) -> Vec<Session> {
        self.inner.sessions.iter().map(|e| e.value().clone()).collect()
    }

    async fn save_player(&self, player: PlayerState) {
        self.inner.players.insert(player.key.clone(), player);
    }

    async fn get_player(&self, key: &PlayerKey) -> Option<PlayerState> {
        self.inner.players.get(key).map(|p| p.clone())
    }

    async fn list_players(&self, session_id: &str) -> Vec<PlayerState> {
        self.inner
            .players
            .iter()
            .filter(|e| e.key().session_id == session_id)
            .map(|e| e.value().clone())
            .collect()
    }

    async fn delete_player(&self, key: &PlayerKey) {
        self.inner.players.remove(key);
    }

    async fn delete_players_for_session(&self, session_id: &str) {
        self.inner.players.retain(|k, _| k.session_id != session_id);
    }

    async fn total_players(&self) -> u32 {
        self.inner.players.len() as u32
    }

    async fn playing_players(&self) -> u32 {
        self.inner
            .players
            .iter()
            .filter(|e| e.value().track.is_some() && !e.value().paused)
            .count() as u32
    }

    async fn player_lock(&self, key: &PlayerKey) -> Arc<Mutex<()>> {
        self.inner
            .locks
            .entry(key.clone())
            .or_insert_with(|| Arc::new(Mutex::new(())))
            .clone()
    }
}

