    #[serde(default, deserialize_with = "double_option")]
    pub rotation: Option<Option<serde_json::Value>>,
    #[serde(default, deserialize_with = "double_option")]
    pub distortion: Option<Option<serde_json::Value>>,
    #[serde(rename = "channelMix", default, deserialize_with = "double_option")]
    pub channel_mix: Option<Option<serde_json::Value>>,
    #[serde(rename = "lowPass", default, deserialize_with = "double_option")]
    pub low_pass: Option<Option<serde_json::Value>>,
    #[serde(rename = "pluginFilters", default, deserialize_with = "double_option")]
    pub plugin_filters: Option<Option<serde_json::Value>>,
}

