    async fn delete_players_for_session(&self, session_id: &str);

    async fn total_players(&self) -> u32;
    async fn playing_players(&self) -> u32;

    /// Per-key advisory lock — callers serialize read-modify-write cycles on
    /// the same `PlayerKey` by holding this guard across `get_player` +
    /// `save_player`. Prevents concurrent PATCHes (e.g. music-module's
